#!/bin/bash
# RPD-RECO data-free prologue, rerun 5 (the director's go to prepare, 2026-11-08: #848 GO at 9634aadf, tested source
# 4fb2add1, coverage-5b-audit https://github.com/josephbaileyy/MINERvA-OmniFold/pull/848#issuecomment-6726690708).
# What it must show: the environment guard, the platform-library pins, the classifier through process exit and the
# post-exit library verification all PASS (data-free-trace.json written). Any STOP is reported as recorded, unrepaired.
# Login node, no Slurm job, 0 node-h, fresh clone, the real MAT source, the traced worker, no analysis input read, no
# flux connect.
# In this connect, in order:
#   1. the COV2D fence: every josephrb job must be named rs1_* or ens1_*; cov2d-* or any other name refuses;
#   2. the fresh clone's HEAD and porcelain, with the blob and sha256 of the five prologue files;
#   3. the policy config, written from this script and checked against its sha256: the draft template
#      late-platform-library-repair-20261108/production-config.draft.json at the head, its slots resolved to rerun 4's
#      values (clone root prologue5-20261108; MAT prefix /pscratch/sd/j/josephrb/MINERvA-OmniFold/MINERvA101/opt;
#      EXTRACT_RUN left unresolved, as in rerun 4: the prologue extracts nothing; the template's RooUnfold build slot
#      "${BOUND_CHECKOUT}/unbinned_unfolding/build" resolved to /pscratch/sd/j/josephrb/MINERvA-OmniFold/unbinned_unfolding/build,
#      the directory the MAT environment puts on LD_LIBRARY_PATH, rerun 4's trace opened and the head's replay test
#      names, test_fd_rpd_reco.py:4827-4829); the five repo pins, re-hashed at the
#      head, are unchanged. The two check scripts are rerun 4's, byte-identical: the C3 and public-export functions are
#      AST-identical between rerun 4's head and this one;
#   4. the strace probe;
#   5. the prologue wrapper at the head. Its stdout and stderr go to $R/wrapper.out and are printed only after the
#      redaction check passes;
#   6. C3 and the redaction check, under MAT_PYTHON -I -S, as in rerun 4;
#   7. only if both pass: a base64 tar of an explicit file list, which names nothing under .rpd-private.
# umask 077. The root /dev/shm/limres-rpd-prologue5-20261108 is refused if it exists, and it is left in place: the
# private record and the root are deleted after the receipt merges, under a ledger row, by a separate connect.
# Launched from a /dev/shm copy of itself ($1), which it deletes.
umask 077
SELF=$1
S=9634aadfa3564e0090caecc4dbf415e1318a2f5f
CFG_SHA=6152adce0eb1987bc349311ec053fe725ee345226b3c16ee724d1cca42242837
C3_SHA=de19736936dacd767c6f4d81ecb502beb3dc049ae3c0718675486644fe12fb96
CHECK_SHA=992be729a3604cf8bae7ea04dfab93aeae9e259b647d3a4d598fd287b2736316
MAT_PYTHON=/global/homes/j/josephrb/.conda/envs/root_6_28/bin/python3
R=/dev/shm/limres-rpd-prologue5-20261108
finish() { echo "== rpd-prologue5 rc=$1 $(date -u +%FT%TZ)"; rm -f -- "$SELF"; exit "$1"; }
case "$(hostname)" in login*) ;; *) echo "STOP: not a login node: $(hostname)"; finish 9 ;; esac
[ ! -e /dev/shm/limres-rpd-prologue5-20261108 ] || { echo "STOP: /dev/shm/limres-rpd-prologue5-20261108 exists"; finish 9; }
echo "node $(hostname) $(date -u +%FT%TZ)"
echo "connect script sha256 $(sha256sum "$SELF" | cut -d' ' -f1)"
echo "== 1. COV2D fence (allowed names: rs1_*, ens1_*; anything else refuses)"
fence=$(squeue -u josephrb -h -o '%i|%j|%T|%M|%l'); frc=$?
echo "squeue rc=$frc; rows:"
printf '%s\n' "$fence"
echo "-- end rows"
bad=$(printf '%s\n' "$fence" | awk -F'|' 'NF && $2 !~ /^(rs1_|ens1_)/')
echo "refusing rows: [$bad]"
[ "$frc" -eq 0 ] && [ -z "$bad" ] || { echo "STOP: the fence is not clear"; finish 3; }
echo "FENCE: clear"
mkdir -m 700 /dev/shm/limres-rpd-prologue5-20261108 || finish 9
echo "== 2. fresh clone at $S"
git clone --quiet --filter=blob:none --no-checkout https://github.com/josephbaileyy/MINERvA-OmniFold.git "$R/repo" || { echo "STOP: clone failed"; finish 5; }
git -C "$R/repo" -c advice.detachedHead=false checkout --quiet "$S" || { echo "STOP: checkout failed"; finish 5; }
head=$(git -C "$R/repo" rev-parse HEAD)
porc=$(git -C "$R/repo" status --porcelain | wc -l)
echo "HEAD $head; porcelain lines $porc"
[ "$head" = "$S" ] && [ "$porc" -eq 0 ] || { echo "STOP: the clone is not $S clean"; finish 5; }
for f in nd-unfolding/fd_rpd_reco_prologue_connect.sh nd-unfolding/fd_rpd_reco_prologue.py nd-unfolding/fd_rpd_reco.py nd-unfolding/fd_rpd_reco_custody.py nd-unfolding/fd_rpd_inputs.py; do
  echo "blob $(git -C "$R/repo" rev-parse "$S:$f" 2>&1) sha256 $(sha256sum "$R/repo/$f" 2>&1 | cut -d' ' -f1) $f"
done
echo "== 3. the policy config and the check scripts"
mkdir "$R/tools" || finish 9
printf '%s' '' | base64 -d > "$R/policy-config.json"
printf '%s' '' | base64 -d > "$R/tools/c3_check.py"
printf '%s' '' | base64 -d > "$R/tools/check_redaction.py"
for pair in "$R/policy-config.json:$CFG_SHA" "$R/tools/c3_check.py:$C3_SHA" "$R/tools/check_redaction.py:$CHECK_SHA"; do
  f=${pair%%:*}; want=${pair##*:}; got=$(sha256sum "$f" | cut -d' ' -f1)
  echo "sha256 $got (expected $want) $f"
  [ "$got" = "$want" ] || { echo "STOP: digest of $f"; finish 5; }
done
echo "== 4. strace probe"
/usr/bin/strace -f -e trace=open,openat,openat2 -o "$R/strace-probe.txt" /bin/true
echo "strace probe rc=$? lines $(wc -l < "$R/strace-probe.txt")"
echo "== 5. the prologue: bash fd_rpd_reco_prologue_connect.sh CHECKOUT CONFIG SHA RUN MAT_PYTHON (output to wrapper.out)"
bash "$R/repo/nd-unfolding/fd_rpd_reco_prologue_connect.sh" "$R/repo" "$R/policy-config.json" "$CFG_SHA" "$R/run" "$MAT_PYTHON" > "$R/wrapper.out" 2>&1
p=$?
echo "prologue wrapper rc=$p; wrapper.out lines $(wc -l < "$R/wrapper.out")"
echo "== run directory and the private tree (mode, size, path; sha256 of every run file)"
find "$R/run" -maxdepth 1 -printf '%M %u %s %P\n' 2>&1 | sort -k4
find "$R/.rpd-private" -printf '%M %u %s %P\n' 2>&1 | sort -k4
for f in "$R"/run/*; do [ -f "$f" ] && echo "sha256 $(sha256sum "$f" | cut -d' ' -f1) ${f#$R/}"; done
[ -f "$R/run/prologue-prepare-reference.json" ] || { echo "STOP: no prepare reference in the run; nothing to check"; finish 6; }
echo "== 6. C3 and the redaction check"
send=()
for f in strace-probe.txt wrapper.out run/trace-policy.json run/prologue-prepare-reference.json run/prologue.strace run/worker.stderr.txt run/worker.stdout.txt run/prologue-prepare.json run/prologue-prepare.STOP.json run/prologue-worker.STOP.json run/prologue-worker.json run/data-free-trace.json run/data-free-trace.STOP.json; do
  if [ -f "$R/$f" ]; then send+=("$f"); else echo "absent (not sent): $f"; fi
done
abs=(); for f in "${send[@]}"; do abs+=("$R/$f"); done
"$MAT_PYTHON" -I -S "$R/tools/c3_check.py" "$R" "$R/run" "${abs[@]}" "$R/policy-config.json" > "$R/c3-check.txt" 2>&1
c3=$?
cat "$R/c3-check.txt"; echo "c3 check rc=$c3"
[ "$c3" -eq 0 ] || { echo "STOP: the C3 check did not pass; nothing is sent"; finish 7; }
priv=$("$MAT_PYTHON" -I -S -c 'import json,sys; print(json.load(open(sys.argv[1]))["private_prepare"]["path"])' "$R/run/prologue-prepare-reference.json")
view=NONE; [ -f "$R/run/prologue-prepare.STOP.json" ] && view="$R/run/prologue-prepare.STOP.json"; [ -f "$R/run/prologue-prepare.json" ] && view="$R/run/prologue-prepare.json"
others=(); for f in "${abs[@]}"; do [ "$f" = "$view" ] || others+=("$f"); done
others+=("$R/policy-config.json" "$R/c3-check.txt")
"$MAT_PYTHON" -I -S "$R/tools/check_redaction.py" "$priv" "$view" "${others[@]}" > "$R/redaction-check.txt" 2>&1
crc=$?
cat "$R/redaction-check.txt"; echo "check rc=$crc"
[ "$crc" -eq 0 ] || { echo "STOP: the redaction check did not pass; nothing is sent"; finish 7; }
echo "== wrapper.out (checked)"
cat "$R/wrapper.out"
echo "== 7. files sent (explicit list)"
send+=(c3-check.txt redaction-check.txt)
for f in "${send[@]}"; do
  case "$f" in *.rpd-private*) echo "STOP: a private path is on the send list"; finish 7 ;; esac
  [ -f "$R/$f" ] || { echo "STOP: $f is missing"; finish 7; }
  echo "sha256 $(sha256sum "$R/$f" | cut -d' ' -f1) $f"
done
echo "== TAR BEGIN"
tar -C "$R" -cf - "${send[@]}" | base64 -w 76
echo "== TAR END tar rc=${PIPESTATUS[0]}"
echo "left in place for the post-merge deletion: $R (the private record under .rpd-private)"
finish "$p"
